DIALOGS = [
[anyone, "prison_break_lord_talk_3", [], "It's not that simple ! I, uh... have developed some business connections with the Slavers. As such, it would be quite bad for me if I interfered with Diego's case. Look, my wife wanted reliable servants, and there is simply no better place to acquire quality worksforce for a fair price than the slave market. They even gave me a discount ! And it's not like I treat the people bought from them with cruelty, so you shouldn't accuse me of being a bad person.", "prison_break_lord_talk_4", []],
]
